from collections import Counter
class Solution:
    def largestPalindromicNumber(self, num: str) -> str:
        c = Counter(num)
        half = ''
        for d in '123456789':
            half += d * (c[d] // 2)
        half += '0' * (c['0'] // 2)
        mid = ''
        for d in '9876543210':
            if c[d] % 2:
                mid = d
                break
        if not half and not mid:
            mid = '0'
        return half + mid + half[::-1]

