class Solution {
public:
    string largestPalindromicNumber(string num) {
        int c[10] = {};
        for (char ch : num) c[ch - '0']++;
        string half;
        for (int d = 1; d <= 9; d++) half += string(c[d] / 2, '0' + d);
        half += string(c[0] / 2, '0');
        char mid = 0;
        for (int d = 9; d >= 0; d--) if (c[d] % 2) { mid = '0' + d; break; }
        if (half.empty() && !mid) mid = '0';
        string r(half.rbegin(), half.rend());
        return half + string(mid ? 1 : 0, mid) + r;
    }
};

