from collections import Counter
class Solution:
    def largestPalindromicNumber(self, num: str) -> str:
        c = Counter(num)
        half = []
        for ch in sorted(num, reverse=True):
            if ch != '0' and c[ch] >= 2:
                half.append(ch)
                c[ch] -= 2
        half += ['0'] * (c['0'] // 2)
        mid = ''
        for d in '9876543210':
            if c[d] % 2 == 1:
                mid = d
                break
        if not half and not mid:
            mid = '0'
        return ''.join(half) + mid + ''.join(reversed(half))

