class Solution {
    public String largestPalindromicNumber(String num) {
        int[] c = new int[10];
        for (char ch : num.toCharArray()) c[ch - '0']++;
        char[] s = num.toCharArray();
        Arrays.sort(s);
        StringBuilder half = new StringBuilder();
        for (int i = s.length - 1; i >= 0; i--) {
            int d = s[i] - '0';
            if (d != 0 && c[d] >= 2) { half.append(s[i]); c[d] -= 2; }
        }
        for (int i = 0; i < c[0] / 2; i++) half.append('0');
        String mid = "";
        for (int d = 9; d >= 0; d--) if (c[d] % 2 == 1) { mid = String.valueOf((char)('0' + d)); break; }
        if (half.length() == 0 && mid.isEmpty()) mid = "0";
        return half.toString() + mid + half.reverse().toString();
    }
}

