var largestPalindromicNumber = function(num) {
    const c = Array(10).fill(0);
    for (const ch of num) c[+ch]++;
    const s = [...num].sort((a, b) => b.localeCompare(a));
    let half = [];
    for (const ch of s) {
        if (ch !== '0' && c[+ch] >= 2) { half.push(ch); c[+ch] -= 2; }
    }
    half = half.concat(Array(Math.floor(c[0] / 2)).fill('0'));
    let mid = '';
    for (let d = 9; d >= 0; d--) if (c[d] % 2 === 1) { mid = String(d); break; }
    if (!half.length && !mid) mid = '0';
    return half.join('') + mid + half.reverse().join('');
};
